function numberOfSteps(num) {
  // Each 1 bit costs one subtraction and every bit after the leading one costs one halving.
  if (num === 0) return 0;
  const bits = num.toString(2);
  const ones = bits.split('').filter(b => b === '1').length;
  return ones + bits.length - 1;
}

